/**
 * Exercise actual generated comparisons through chooser, source links, warnings, missing editions and accessibility.
 * State is built static HTML and browser controls, with no API mocks or invented source answers.
 * Symbol index (generated by tools/update-symbol-index.ts):
 * @@SYMBOL_INDEX_START
 * - variable WCAG_TAGS: line 11
 * @@SYMBOL_INDEX_END
 */
import AxeBuilder from "@axe-core/playwright";
import { expect, test } from "@playwright/test";
const WCAG_TAGS = ["wcag2a", "wcag2aa", "wcag21aa", "wcag22aa"];

test("support engineer compares reused E-104 meaning through the original topic's version links", async ({
  page,
}) => {
  await page.goto("/docs/apex-control-hub/1.5/error-e-104/");
  await page.getByRole("link", { name: "Compare with 2.0 (current)" }).click();
  await expect(page).toHaveURL(/\/compare\/apex-control-hub\/1.5\/2.0\/error-e-104\/$/u);
  const before = page.locator('[data-edition="from"]');
  const after = page.locator('[data-edition="to"]');
  await expect(before).toContainText("Ethernet address conflicts");
  await expect(after).toContainText("trust certificate has expired");
  await expect(page.locator('[data-warning-status="changed"]')).toBeVisible();
  await expect(before.getByRole("link", { name: "Read canonical 1.5 source" })).toHaveAttribute(
    "href",
    "/docs/apex-control-hub/1.5/error-e-104/",
  );
  await expect(after.getByRole("link", { name: "Read canonical 2.0 source" })).toHaveAttribute(
    "href",
    "/docs/apex-control-hub/2.0/error-e-104/",
  );
  for (const edition of [before, after]) {
    await expect(edition.getByText("Condition", { exact: true })).toBeVisible();
    await expect(edition.getByText("Consequence", { exact: true })).toBeVisible();
    await expect(edition.getByText("Avoidance", { exact: true })).toBeVisible();
    await expect(edition.getByText("Checksum", { exact: true })).toBeVisible();
  }
});

test("documentation owner uses product-bound chooser and reviews a warning absent in an older edition", async ({
  page,
}) => {
  await page.goto("/compare/");
  await page.getByLabel("Comparison product").selectOption("northstar-io-gateway");
  await page.getByLabel("From version").selectOption("3.2");
  await page.getByLabel("To version").selectOption("3.0");
  await page.getByLabel("Topic identity").selectOption("analog-input-calibration");
  await expect(page.getByLabel("To version").locator('option[value="1.5"]')).toHaveCount(0);
  await page.getByRole("button", { name: "Compare editions" }).focus();
  await page.keyboard.press("Enter");
  await expect(page).toHaveURL(
    /\/compare\/northstar-io-gateway\/3.2\/3.0\/analog-input-calibration\/$/u,
  );
  await expect(page.locator('[data-warning-status="absent"]')).toBeVisible();
  await expect(
    page.getByText(/Warning absent from target documentation; no risk resolution is implied/u),
  ).toBeVisible();
  await expect(page.locator('[data-edition="from"]')).toContainText(
    "reviewed manual or maintenance state",
  );
  await expect(page.locator('[data-edition="to"] .warning-notice')).toHaveCount(0);
  await page.getByRole("link", { name: "Reverse comparison" }).click();
  await expect(page.locator('[data-warning-status="added"]')).toBeVisible();
  await expect(page.locator('[data-edition="to"]')).toContainText(
    "reviewed manual or maintenance state",
  );
});

test("retired edition stays labeled and missing topic is not substituted from a current version", async ({
  page,
}) => {
  await page.goto("/compare/apex-control-hub/2.0/1.0/error-e-104/");
  const after = page.locator('[data-edition="to"]');
  await expect(after.getByText("Retired documentation", { exact: true })).toBeVisible();
  await expect(after.getByText(/This topic is not documented in this edition/u)).toBeVisible();
  await expect(after.getByRole("link", { name: /Read canonical/u })).toHaveCount(0);
  await expect(after.locator(".topic-section")).toHaveCount(0);
  await expect(page.locator('[data-edition="from"] .topic-section')).toHaveCount(2);
});

test("new topic has an explicit missing source edition and no invented procedure", async ({
  page,
}) => {
  await page.goto("/compare/apex-control-hub/1.5/2.0/quickstart/");
  await expect(page.locator('[data-edition="from"] .missing-topic')).toBeVisible();
  await expect(page.locator('[data-edition="from"] .topic-section')).toHaveCount(0);
  await expect(page.locator('[data-edition="to"] .topic-section').first()).toBeVisible();
});

test("chooser rejects an injected non-allowlisted topic without navigating", async ({ page }) => {
  await page.goto("/compare/");
  await page.getByLabel("Topic identity").evaluate((element) => {
    const select = element as HTMLSelectElement;
    select.add(new Option("Injected", "../external"));
    select.value = "../external";
  });
  await page.getByRole("button", { name: "Compare editions" }).click();
  await expect(page.getByRole("status")).toHaveText(
    "Choose a documented topic and two distinct versions.",
  );
  await expect(page).toHaveURL(/\/compare\/$/u);
});

for (const path of [
  "/compare/",
  "/compare/apex-control-hub/1.5/2.0/error-e-104/",
  "/compare/northstar-io-gateway/3.2/3.0/analog-input-calibration/",
  "/compare/apex-control-hub/2.0/1.0/error-e-104/",
]) {
  test(`comparison reflow, unique anchors and automated accessibility: ${path}`, async ({
    page,
  }) => {
    await page.goto(path);
    const dimensions = await page.evaluate(() => ({
      viewport: document.documentElement.clientWidth,
      content: document.documentElement.scrollWidth,
      ids: [...document.querySelectorAll("[id]")].map((element) => element.id),
    }));
    expect(dimensions.content).toBeLessThanOrEqual(dimensions.viewport);
    expect(new Set(dimensions.ids).size).toBe(dimensions.ids.length);
    const results = await new AxeBuilder({ page }).withTags(WCAG_TAGS).analyze();
    expect(results.violations).toEqual([]);
  });
}

test("static comparison and fallback links work without JavaScript", async ({
  browser,
  baseURL,
}) => {
  const context = await browser.newContext({ javaScriptEnabled: false });
  try {
    const page = await context.newPage();
    await page.goto(`${baseURL ?? "http://127.0.0.1:4321"}/compare/`);
    await page.getByRole("link", { name: "apex-control-hub: 1.5 to 2.0, error-e-104" }).click();
    await expect(page.locator('[data-edition="from"]')).toContainText("Ethernet address conflicts");
    await expect(page.locator('[data-edition="to"]')).toContainText(
      "trust certificate has expired",
    );
  } finally {
    await context.close();
  }
});
